		r = uint8((val >> 16) & 0xff)
		g = uint8((val >> 8) & 0xff)
		b = uint8(val & 0xff)
		a = 0xff

	case 8:
		// RRGGBBAA
		val, err := strconv.ParseUint(hex, 16, 64)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
