package binding

import (
	"fmt"
)

// sprintf is a String binding that formats values from other bindings using fmt.Sprintf
type sprintf struct {
	base
	format string
	values []DataItem
}

// NewSprintf creates a new String binding that formats the values from the provided bindings
// using fmt.Sprintf with the given format string. When any of the source bindings change,
// this binding updates with the newly formatted string.
//
// Example:
//   name := binding.NewString()
//   name.Set("Alice")
//   age := binding.NewInt()
//   age.Set(30)
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//   // formatted.Get() returns "Name: Alice, Age: 30"
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintf{
		format: format,
		values: bindings,
	}

	// Listen to all source bindings for changes
	for _, b := range bindings {
		b.AddListener(s)
	}

	return s
}

// Get returns the formatted string using the current values of all source bindings
func (s *sprintf) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	values := make([]interface{}, len(s.values))
	for i, b := range s.values {
		switch v := b.(type) {
		case String:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Int:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Float:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Bool:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Untyped:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		default:
			// For other types, try to get via Untyped interface
			if u, ok := b.(Untyped); ok {
				val, err := u.Get()
				if err != nil {
					return "", err
				}
				values[i] = val
			} else {
				values[i] = b
			}
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

// Set is not supported for sprintf bindings as they are read-only derived values
func (s *sprintf) Set(string) error {
	return fmt.Errorf("sprintf binding is read-only")
}

// DataChanged is called when any source binding changes, triggering update to listeners
func (s *sprintf) DataChanged() {
	s.trigger()
}

// StringToStringWithFormat creates a new String binding that formats the value from the source
// String binding using fmt.Sprintf with the given format string.
//
// Example:
//   name := binding.NewString()
//   name.Set("Alice")
//   greeting := binding.StringToStringWithFormat(name, "Hello, %s!")
//   // greeting.Get() returns "Hello, Alice!"
//
// Since: 2.2
func StringToStringWithFormat(source String, format string) String {
	return NewSprintf(format, source)
}

