// allStrings is a validator combinator that runs multiple validators in sequence.
type allStrings struct {
	validators []fyne.StringValidator
}

// Validate runs all validators in order and returns the first error encountered.
// If all validators pass, returns nil.
func (v *allStrings) Validate(text string) error {
	for _, validator := range v.validators {
		if err := validator.Validate(text); err != nil {
			return err
		}
	}
	return nil
}

// NewAllStrings creates a validator combinator that runs all provided validators in order.
// It returns the first error encountered, or nil if all validators pass.
// This enables chaining multiple validators together (e.g., time format validation
// and regexp validation together).
//
// Example:
//   validator := validation.NewAllStrings(
//       validation.NewRegexp(`^\d{4}-\d{2}-\d{2}$`, "Invalid date format"),
//       validation.NewTime("2006-01-02"),
//   )
//   entry.Validator = validator
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return &allStrings{validators: validators}
}

